// ─── Building icons (SVG, drawn at hex center cx/cy) ─────────────────────────

// Store circle positions — slightly inside hex corners (r≈12 from center, S=18)
// Corner angles: 30°(10,6), 90°(0,12), 150°(-10,6), 210°(-10,-6), 270°(0,-12), 330°(10,-6)
const C6 = [[10,6],[0,12],[-10,6],[-10,-6],[0,-12],[10,-6]]; // all 6 corners
const C4 = [[10,6],[-10,6],[-10,-6],[10,-6]];                // 4 side corners
const C3 = [[10,6],[0,12],[-10,6]];                          // bottom 3 corners
const STORE_POS = {
    cryo_tank:    C4,
    food_plant:   C6,
    oxygen_plant: C6,
    laboratory:   C6,
    research_site:C6,
    rover:        C6,
    separator:    C6,
    workshop:     C6,
    transceiver:  C3,
    recycler:     C4,
};

function ShuttleIcon({ cx, cy, size }) {
    const s = size / 16;
    const fg = BLD_FG.shuttle;
    return (
        <g>
            {/* body */}
            <rect x={cx - 2*s} y={cy - 5*s} width={4*s} height={8*s} rx={s} fill={fg} />
            {/* nose cone */}
            <polygon points={`${cx},${cy - 8*s} ${cx - 2*s},${cy - 5*s} ${cx + 2*s},${cy - 5*s}`} fill={fg} />
            {/* left fin */}
            <polygon points={`${cx - 2*s},${cy + 1*s} ${cx - 4.5*s},${cy + 3.5*s} ${cx - 2*s},${cy + 3*s}`} fill={fg} opacity={0.8} />
            {/* right fin */}
            <polygon points={`${cx + 2*s},${cy + 1*s} ${cx + 4.5*s},${cy + 3.5*s} ${cx + 2*s},${cy + 3*s}`} fill={fg} opacity={0.8} />
            {/* exhaust flame */}
            <ellipse cx={cx} cy={cy + 4*s} rx={1.5*s} ry={2*s} fill="#f97316" opacity={0.75} />
        </g>
    );
}

function BuildingIcon({ type, cx, cy, filled = 0, generated = 0, cap = 0, storeColor = '#fbbf24', size = 20, onStoreAdjust, setupStep = 0 }) {
    const positions = STORE_POS[type];
    const half = size / 2;
    // 분리기: setupStep에 따라 다른 PNG 사용
    const iconSuffix = type === 'separator'
        ? (setupStep >= 3 ? '_step3' : setupStep >= 2 ? '_step2' : '')
        : '';
    return (
        <g>
            {type === 'shuttle'
                ? <ShuttleIcon cx={cx} cy={cy} size={size} />
                : <image
                    href={`/icons/buildings/${type}_ink${iconSuffix}.png`}
                    x={cx - half} y={cy - half}
                    width={size} height={size}
                    style={{ filter: 'invert(1)', mixBlendMode: 'screen' }}
                />
            }
            {positions && positions.map(([dx, dy], i) => {
                if (i >= generated) return null;
                const isFilled  = i < filled;
                const canUse    = onStoreAdjust && isFilled && i === filled - 1;
                const canRefill = onStoreAdjust && !isFilled && i === filled;
                let op = null;
                if (canUse)         op = 'use';
                else if (canRefill) op = 'refill';
                const clickable = op !== null;
                return (
                    <circle key={i} cx={cx+dx} cy={cy+dy} r={clickable ? 2.2 : 1.65}
                        fill={isFilled ? storeColor : 'none'}
                        stroke={storeColor} strokeWidth={0.5} opacity={0.88}
                        style={{ cursor: clickable ? 'pointer' : 'default' }}
                        onClick={clickable ? (e) => { e.stopPropagation(); onStoreAdjust(op); } : undefined}
                    />
                );
            })}
            {/* Gain button: invisible slot just past generated, shown as dim "+" */}
            {positions && generated < cap && onStoreAdjust && (() => {
                const pos = positions[generated];
                if (!pos) return null;
                const [dx, dy] = pos;
                return (
                    <circle key="gain" cx={cx+dx} cy={cy+dy} r={2.2}
                        fill="none" stroke={storeColor} strokeWidth={0.5} opacity={0.35}
                        style={{ cursor: 'pointer' }}
                        onClick={(e) => { e.stopPropagation(); onStoreAdjust('gain'); }}
                    />
                );
            })()}
        </g>
    );
}

