function DieFace({ value, size = 64, selected, dimmed, onClick }) {
    const fill = selected ? '#78350f' : '#16082e';
    const ring = selected ? '#fbbf24' : '#4c1d95';
    return (
        <button
            onClick={onClick}
            disabled={!onClick}
            className={`rounded-2xl transition-all duration-150 active:scale-95 ${selected ? 'scale-110 shadow-lg shadow-amber-500/30' : ''} ${dimmed ? 'opacity-30 cursor-default' : ''}`}
            style={{ width: size, height: size, background: fill, border: `2px solid ${ring}`, cursor: onClick ? 'pointer' : 'default' }}
        >
            <svg width={size} height={size} viewBox="0 0 100 100">
                {(PIPS[value] || []).map(([cx, cy], i) => (
                    <circle key={i} cx={cx} cy={cy} r={9}
                        fill={selected ? '#fbbf24' : '#c4b5fd'} />
                ))}
            </svg>
        </button>
    );
}

function DieInput({ value, onChange }) {
    const dec = () => onChange(value == null ? 1 : Math.max(1, value - 1));
    const inc = () => onChange(value == null ? 1 : Math.min(6, value + 1));
    return (
        <div className="flex flex-col items-center gap-1.5">
            <button onClick={inc} className="w-10 h-8 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 text-white active:scale-95 transition-all">
                <ChevronUp size={16} />
            </button>
            <div className="rounded-2xl flex items-center justify-center"
                style={{ width: 64, height: 64, background: '#16082e', border: `2px solid ${value ? '#7c3aed' : '#2d1a52'}` }}>
                {value ? (
                    <svg width={60} height={60} viewBox="0 0 100 100">
                        {(PIPS[value] || []).map(([cx, cy], i) => (
                            <circle key={i} cx={cx} cy={cy} r={9} fill="#c4b5fd" />
                        ))}
                    </svg>
                ) : (
                    <span className="text-2xl font-bold text-white/20">?</span>
                )}
            </div>
            <button onClick={dec} className="w-10 h-8 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 text-white active:scale-95 transition-all">
                <ChevronDown size={16} />
            </button>
        </div>
    );
}

// 자원 circle 트랙 (최대 31칸, T마크 지원)
function ResourceTrack({ value, max = 31, color, tMarks = [], label, emoji, peak }) {
    return (
        <div className="flex items-start gap-2">
            {/* 레이블 영역 */}
            <div className="flex items-center gap-1.5 w-[52px] flex-shrink-0 pt-0.5">
                <span className="text-sm leading-none">{emoji}</span>
                <div>
                    <div className="text-[9px] text-white/40 leading-none">{label}</div>
                    <div className="text-sm font-black leading-none mt-[1px]" style={{ color }}>{value}</div>
                </div>
            </div>
            {/* Circle 트랙 */}
            <div className="flex flex-col gap-[2px]">
                {/* T 마크 행 (정신력만) */}
                {tMarks.length > 0 && (
                    <div className="flex gap-[2px]">
                        {Array.from({ length: max }, (_, i) => {
                            const pos = i + 1;
                            const isT = tMarks.includes(pos);
                            const usedCount = peak !== undefined ? Math.max(0, peak - value) : 0;
                            const isFilled = pos > usedCount && pos <= usedCount + value;
                            return (
                                <div key={pos} style={{ width: 7, height: 6 }}
                                    className="flex items-end justify-center">
                                    {isT && (
                                        <span className="text-[6px] font-black leading-none"
                                            style={{ color: isFilled ? '#fbbf24' : '#78716c' }}>T</span>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
                {/* Circle 행 */}
                <div className="flex gap-[2px] flex-wrap">
                    {Array.from({ length: max }, (_, i) => {
                        const pos      = i + 1;
                        const usedCount = peak !== undefined ? Math.max(0, peak - value) : 0;
                        const used   = pos <= usedCount;
                        const filled = pos > usedCount && pos <= usedCount + value;
                        const isT    = tMarks.includes(pos);
                        return (
                            <div
                                key={pos}
                                className="rounded-[1px] transition-colors duration-200"
                                style={{
                                    width: 7, height: 7,
                                    background: filled ? color
                                              : used   ? color + '30'
                                              : '#0e0924',
                                    border: `1px solid ${
                                        isT
                                            ? filled ? '#fbbf24' : '#6b6b40'
                                            : filled ? color + 'aa'
                                            : used   ? color + '50'
                                            : '#1e1340'
                                    }`,
                                }}
                            />
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

