function HexMap({ buildings, roverBuilt, onHexClick, validHexes = new Set(), advanceHexes = new Set(), onStoreAdjust,
                   pendingProduce, pendingConsume, onProduceClick, onConsumeClick }) {
    const S = 18;
    const hexes = generateHexGrid(MAP_RADIUS);
    return (
        <svg viewBox="-143 -129 286 258" className="w-full max-w-[300px] mx-auto block">
            {hexes.map(({ q, r }) => {
                const { x, y } = hexToPixel(q, r, S);
                const key = `${q},${r}`;
                const terrain = TERRAIN_MAP[key] || TERRAIN.BLANK;
                const bld = buildings[key];
                const isOuter = Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) === MAP_RADIUS;
                const locked = isOuter && !roverBuilt;
                const isValid   = validHexes.has(key);
                const isAdvance = advanceHexes.has(key);  // 기존 미완성 건물 (step 진행)

                // 생산 타겟
                const produceTypes = pendingProduce
                    ? (pendingProduce.buildingTypes || (pendingProduce.buildingType ? [pendingProduce.buildingType] : []))
                    : [];
                const isProduceTarget = !locked && bld && produceTypes.includes(bld.type) && bld.active;
                // 소모 타겟
                const isConsumeTarget = !locked && bld && pendingConsume
                    && BUILDINGS[bld.type]?.storeRes === pendingConsume.resType && (bld.store || 0) > 0;

                const fill = locked ? '#0d0820'
                    : isProduceTarget ? '#143020'
                    : isConsumeTarget ? '#2a1010'
                    : isAdvance ? '#0a1f2e'
                    : isValid ? '#14301a'
                    : TERRAIN_FILL[terrain];
                const stroke = locked ? '#180d30'
                    : isProduceTarget ? '#22c55e'
                    : isConsumeTarget ? '#ef4444'
                    : isAdvance ? '#38bdf8'
                    : isValid ? '#16a34a'
                    : '#3a2060';
                const strokeWidth = (isProduceTarget || isConsumeTarget || isAdvance || isValid) ? 1.5 : 1;

                const clickHandler = isProduceTarget && onProduceClick
                    ? () => onProduceClick(key, Math.max(1, pendingProduce.amt))
                    : isConsumeTarget && onConsumeClick
                    ? () => onConsumeClick(key, bld.store || 0)
                    : (isAdvance || isValid) && onHexClick
                    ? () => onHexClick(q, r)
                    : undefined;

                const pts = hexCorners(x, y, S - 1).map(([px, py]) => `${px.toFixed(1)},${py.toFixed(1)}`).join(' ');
                const mark = TERRAIN_MARK[terrain];

                return (
                    <g key={key}
                       onClick={clickHandler}
                       style={{ cursor: clickHandler ? 'pointer' : 'default' }}>
                        <polygon points={pts} fill={fill} stroke={stroke} strokeWidth={strokeWidth} />
                        {/* 건물 없을 때만 지형 기호 표시 */}
                        {mark && !locked && !bld && (
                            <text x={x} y={y + 2} textAnchor="middle" fontSize="6" fill={mark.color}
                                style={{ userSelect: 'none', pointerEvents: 'none' }}>
                                {mark.char}
                            </text>
                        )}
                        {/* 건물 아이콘 + 로컬 저장량 원 */}
                        {bld && (() => {
                            const def = BUILDINGS[bld.type];
                            const hasStore = def?.storeCap && def?.storeRes;
                            const filled    = hasStore ? (bld.store || 0) : 0;
                            const generated = hasStore ? (bld.generated ?? (def.storeInit || 0)) : 0;
                            const cap       = hasStore ? def.storeCap : 0;
                            const storeColor =
                                def?.storeRes === 'food'       ? '#4ade80' :
                                def?.storeRes === 'oxygen'     ? '#22d3ee' :
                                def?.storeRes === 'sanity'     ? '#a78bfa' :
                                def?.storeRes === 'batteries'  ? '#60a5fa' :
                                def?.storeRes === 'automatron' ? '#c084fc' :
                                '#fbbf24';
                            return (
                                <BuildingIcon type={bld.type} cx={x} cy={y}
                                    filled={filled} generated={generated} cap={cap} storeColor={storeColor}
                                    setupStep={bld.setupStep || (bld.active ? 99 : 0)}
                                    onStoreAdjust={onStoreAdjust ? (op) => onStoreAdjust(key, op) : undefined} />
                            );
                        })()}
                    </g>
                );
            })}
        </svg>
    );
}

