const MOBILE_MQ = '(max-width: 767px)';

export default function RecycledGame({ onBack }) {
    const { state, setDie, confirmInput, toggleDie, confirmSelect,
        doAction, toggleCombine, startConstruction, selectBuilding, cancelConstruction, placeBuilding,
        startBuildingSetup, placeBuildingSetup, advanceBuildingSetup,
        confirmProduce, confirmConsume, skipConsume, selectConnection,
        endActions, setAccidentDie, resolveAccident, resolveConsumption,
        chooseTech, restart, debugStart, adjustBuildingStore } = useRecycledGame();

    const [legendOpen, setLegendOpen] = useState(false);
    const [rulesOpen,  setRulesOpen]  = useState(false);
    const [debugPanelOpen, setDebugPanelOpen] = useState(false);
    const [isMobile, setIsMobile] = useState(() => window.matchMedia(MOBILE_MQ).matches);
    const [leftTab, setLeftTab] = useState('action');
    // 생산/소모 개수 입력 모달
    const [amtModal, setAmtModal] = useState(null);
    // null | { kind: 'produce', hexKey, maxAmt }
    //       | { kind: 'consume', source, maxAmt, label, emoji }

    useEffect(() => {
        const mql = window.matchMedia(MOBILE_MQ);
        const handler = (e) => setIsMobile(e.matches);
        mql.addEventListener('change', handler);
        return () => mql.removeEventListener('change', handler);
    }, []);

    // 건물 배치 모드일 때 유효한 헥스 계산
    const validHexes = useMemo(() => {
        const step = state.construction?.step;
        if (step !== 'place' && step !== 'place_setup') return new Set();
        const type = state.construction.buildingType;
        const result = new Set();

        if (step === 'place_setup') {
            generateHexGrid(MAP_RADIUS).forEach(({ q, r }) => {
                const key = `${q},${r}`;
                if (state.buildings[key]) return;
                const isOuter = Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) === MAP_RADIUS;
                if (isOuter && !state.roverBuilt) return;
                if (type === 'separator') {
                    const terrain = TERRAIN_MAP[key];
                    if (terrain === TERRAIN.TRASH) result.add(key);
                } else if (type === 'recycler') {
                    const hasAdj = [[1,0],[1,-1],[0,-1],[-1,0],[-1,1],[0,1]]
                        .some(([dq, dr]) => {
                            const n = state.buildings[`${q+dq},${r+dr}`];
                            return n?.type === 'separator' && n.active;
                        });
                    if (hasAdj) result.add(key);
                }
            });
            return result;
        }

        const recyclerMats = Object.values(state.buildings).filter(b => b.type === 'recycler').reduce((s, b) => s + (b.store || 0), 0);
        const localPower   = Object.values(state.buildings).filter(b => b.type === 'nuclear_pod' || b.type === 'amplifier').reduce((s, b) => s + (b.store || 0), 0);
        const ctx = {
            buildings: state.buildings, roverBuilt: state.roverBuilt,
            apRemaining: state.apPool - state.apUsed,
            materials: state.materials + recyclerMats,
            power: state.power + localPower,
        };
        generateHexGrid(MAP_RADIUS).forEach(({ q, r }) => {
            if (canPlaceBuilding(ctx, type, q, r)) result.add(`${q},${r}`);
        });
        return result;
    }, [state.construction, state.buildings, state.roverBuilt, state.apPool, state.apUsed, state.materials, state.power]);

    // place_setup 모드에서 step 진행 가능한 기존 미완성 건물 헥스
    const advanceHexes = useMemo(() => {
        if (state.construction?.step !== 'place_setup') return new Set();
        const type = state.construction.buildingType;
        const result = new Set();
        Object.entries(state.buildings).forEach(([key, b]) => {
            if (b.type === type && !b.active) result.add(key);
        });
        return result;
    }, [state.construction, state.buildings]);

    const renderPhase = () => {
        if (state.gameOver || state.victory)
            return <PhaseOver state={state} restart={restart} />;

        switch (state.phase) {
            case 'input':       return <PhaseInput state={state} setDie={setDie} confirmInput={confirmInput} />;
            case 'select':      return <PhaseSelect state={state} toggleDie={toggleDie} confirmSelect={confirmSelect} />;
            case 'action':      return <PhaseAction state={state} doAction={doAction} toggleCombine={toggleCombine}
                                    startConstruction={startConstruction} selectBuilding={selectBuilding}
                                    cancelConstruction={cancelConstruction} startBuildingSetup={startBuildingSetup}
                                    selectConnection={selectConnection}
                                    endActions={endActions} />;
            case 'accident':    return <PhaseAccident state={state} setAccidentDie={setAccidentDie} resolveAccident={resolveAccident} />;
            case 'consumption': return <PhaseConsumption state={state} resolveConsumption={resolveConsumption} skipConsume={skipConsume} />;
            default:            return null;
        }
    };

    const phaseLabel = {
        input: '입력', select: '선택', action: '행동',
        accident: '사고', consumption: '소모',
    }[state.phase] ?? '—';

    // 공통 블록들
    const headerBlock = (
        <div className="flex items-center gap-3 mb-4">
            {onBack && (
                <button onClick={onBack}
                    className="p-2 rounded-xl text-slate-400 hover:text-white bg-white/5 hover:bg-white/10 transition-all">
                    <ArrowLeft size={18} />
                </button>
            )}
            <div className="flex-1">
                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-xs font-semibold uppercase tracking-widest text-purple-400/70">RECYCLED</p>
                        <p className="text-sm font-bold text-white leading-none">
                            턴 <span className="text-purple-300">{state.turn}</span>
                            <span className="text-white/30"> / 75</span>
                        </p>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <div className="text-xs px-2.5 py-1 rounded-full font-semibold"
                            style={{ background: '#1e0f38', color: '#a78bfa', border: '1px solid #4c1d95' }}>
                            {phaseLabel}
                        </div>
                        <button onClick={() => setDebugPanelOpen(o => !o)}
                            title="디버그"
                            className="text-xs px-1.5 py-1 rounded-full transition-all"
                            style={{ background: state.debugMode ? '#422006' : '#1a1a1a', color: state.debugMode ? '#fb923c' : '#6b7280', border: `1px solid ${state.debugMode ? '#c2410c' : '#374151'}` }}>
                            🔧
                        </button>
                    </div>
                </div>
                <div className="mt-1.5 w-full h-1 rounded-full overflow-hidden" style={{ background: '#1a0f2e' }}>
                    <div className="h-full rounded-full transition-all duration-500"
                        style={{ width: `${(state.turn / 75) * 100}%`, background: 'linear-gradient(90deg,#7c3aed,#c026d3)' }} />
                </div>
            </div>
        </div>
    );

    const debugBlock = debugPanelOpen && (
        <div className="mb-3 px-3 py-2.5 rounded-xl flex items-center gap-3"
            style={{ background: '#1c0d00', border: '1px solid #c2410c' }}>
            <span className="text-xs text-orange-400/70 font-semibold flex-1">
                🔧 {state.debugMode ? '디버그 ON (주사위 6,6,6 고정)' : '디버그 OFF'}
            </span>
            <button onClick={() => { debugStart(); setDebugPanelOpen(false); }}
                className="text-xs px-3 py-1.5 rounded-lg font-semibold transition-all active:scale-95"
                style={{ background: '#7c2d12', color: '#fed7aa', border: '1px solid #c2410c' }}>
                자원 31로 초기화
            </button>
        </div>
    );

    const depotBlock = (
        <div className="mb-3">
            <DepotSection state={state}
                pendingConsume={state.pendingConsume}
                onConsumeSource={(source, available, label, emoji) =>
                    setAmtModal({ kind: 'consume', source, maxAmt: Math.min(available, state.pendingConsume?.remaining ?? 0), label, emoji })} />
            <div className="mt-1.5">
                <ShuttleStatus state={state} />
            </div>
        </div>
    );

    const phaseBlock = (
        <div className="rounded-2xl p-4 mb-4" style={{ background: '#0d0820', border: '1px solid #2d1a52' }}>
            {renderPhase()}
        </div>
    );

    const hexMapBlock = (
        <div className="rounded-2xl p-3" style={{ background: '#0d0820', border: '1px solid #2d1a52' }}>
            <div className="flex items-center justify-between mb-2">
                <button onClick={() => setLegendOpen(true)}
                    className="text-[10px] font-semibold px-2 py-1 rounded-lg transition-all hover:brightness-110 active:scale-95"
                    style={{ background: '#1e0f38', color: '#a78bfa', border: '1px solid #4c1d95' }}>
                    🏗 도감
                </button>
                <p className="text-xs font-semibold uppercase tracking-widest text-purple-400/50">
                    {(state.construction?.step === 'place' || state.construction?.step === 'place_setup') ? '🟢 헥스를 선택하세요' : 'Planet 1 — 지도'}
                </p>
                <button onClick={() => setRulesOpen(true)}
                    className="text-[10px] font-semibold px-2 py-1 rounded-lg transition-all hover:brightness-110 active:scale-95"
                    style={{ background: '#062030', color: '#67e8f9', border: '1px solid #164e63' }}>
                    ℹ 룰
                </button>
            </div>
            <HexMap buildings={state.buildings} roverBuilt={state.roverBuilt}
                validHexes={validHexes}
                advanceHexes={advanceHexes}
                onStoreAdjust={adjustBuildingStore}
                pendingProduce={state.pendingProduce}
                pendingConsume={state.pendingConsume}
                onProduceClick={(hexKey, maxAmt) => setAmtModal({ kind: 'produce', hexKey, maxAmt })}
                onConsumeClick={(hexKey, available) => setAmtModal({
                    kind: 'consume', source: hexKey,
                    maxAmt: Math.min(available, state.pendingConsume?.remaining ?? 0),
                    label: BUILDINGS[state.buildings[hexKey]?.type]?.name ?? hexKey,
                    emoji: '🏗',
                })}
                onHexClick={
                    state.construction?.step === 'place'
                        ? (q, r) => placeBuilding(state.construction.buildingType, q, r)
                    : state.construction?.step === 'place_setup'
                        ? (q, r) => {
                            const key = `${q},${r}`;
                            if (state.buildings[key]) advanceBuildingSetup(key);
                            else placeBuildingSetup(state.construction.buildingType, q, r);
                        }
                    : null
                } />
            <div className="flex justify-center flex-wrap gap-3 mt-2">
                {[
                    { char: '♲', label: '쓰레기', color: '#a16207' },
                    { char: '❄', label: '얼음', color: '#0891b2' },
                    { char: '◉', label: '분화구', color: '#7c3aed' },
                    { char: '■', label: '건물', color: '#fbbf24' },
                    { char: '●', label: '배치가능', color: '#16a34a' },
                ].map(({ char, label, color }) => (
                    <div key={label} className="flex items-center gap-1">
                        <span className="text-sm" style={{ color }}>{char}</span>
                        <span className="text-[10px] text-white/40">{label}</span>
                    </div>
                ))}
            </div>
        </div>
    );

    const tabBar = (
        <div className="flex gap-1 rounded-xl p-1 mb-3" style={{ background: '#1a0f2e' }}>
            {[{ key: 'depot', label: '저장고' }, { key: 'action', label: '액션' }].map(({ key, label }) => (
                <button key={key} onClick={() => setLeftTab(key)}
                    className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${leftTab === key ? 'text-white' : 'text-white/40 hover:text-white/70'}`}
                    style={leftTab === key ? { background: '#5b21b6' } : {}}>
                    {label}
                </button>
            ))}
        </div>
    );

    return (
        <div className="relative min-h-screen bg-[#0a0118] pb-10">
            {/* Ambient */}
            <div className="pointer-events-none absolute inset-0 overflow-hidden">
                <div className="absolute -top-20 left-1/4 h-72 w-72 rounded-full bg-purple-700/10 blur-[100px]" />
                <div className="absolute top-1/2 right-0 h-64 w-64 rounded-full bg-orange-700/10 blur-[100px]" />
            </div>

            {isMobile ? (
                /* ── 모바일: 단일 세로 컬럼 ── */
                <div className="relative container mx-auto max-w-md px-4 pt-4">
                    {headerBlock}
                    {debugBlock}
                    {tabBar}
                    {leftTab === 'depot' ? depotBlock : phaseBlock}
                    {hexMapBlock}
                </div>
            ) : (
                /* ── 데스크탑: 2단 가로 레이아웃 ── */
                <div className="relative px-4 pt-4">
                    {headerBlock}
                    {debugBlock}
                    <div className="flex gap-4 items-start">
                        {/* 왼쪽: 탭 (저장고 / 액션) */}
                        <div className="flex-1 min-w-0">
                            {tabBar}
                            {leftTab === 'depot' ? depotBlock : phaseBlock}
                        </div>
                        {/* 오른쪽: 헥스 맵 */}
                        <div className="flex-1 min-w-0">
                            {hexMapBlock}
                        </div>
                    </div>
                </div>
            )}

            {/* 기술 보너스 모달 */}
            {state.pendingTech && <TechChoiceModal state={state} chooseTech={chooseTech} />}
            {/* 건물 도감 모달 */}
            {legendOpen && <BuildingLegendModal onClose={() => setLegendOpen(false)} />}
            {/* 룰 요약 모달 */}
            {rulesOpen && <RulesSummaryModal onClose={() => setRulesOpen(false)} />}
            {/* 생산/소모 개수 입력 모달 */}
            {amtModal && amtModal.kind === 'produce' && (
                <AmountModal
                    title={`생산 개수 선택`}
                    subtitle={`최대 ${amtModal.maxAmt}개를 생산할 수 있습니다`}
                    min={1} max={amtModal.maxAmt}
                    onConfirm={(amt) => { confirmProduce(amtModal.hexKey, amt); setAmtModal(null); }}
                    onCancel={() => setAmtModal(null)}
                />
            )}
            {amtModal && amtModal.kind === 'consume' && (
                <AmountModal
                    title={`${amtModal.emoji} ${amtModal.label}에서 소모`}
                    subtitle={`최대 ${amtModal.maxAmt}개 소모 가능`}
                    min={1} max={amtModal.maxAmt}
                    onConfirm={(amt) => { confirmConsume(amtModal.source, amt); setAmtModal(null); }}
                    onCancel={() => setAmtModal(null)}
                />
            )}
        </div>
    );
}
